    /**
     * Generic method to transform binary expressions, which are parsed
     * according to these rules:
     * __fre_binary_ScheduleExpression = [ScheduleExpression / __fre_binary_operator]2+ ;
     * leaf __fre_binary_operator = 'and' | 'or' | '==' | '*' | '+' | '-' | '/' | '<' | '>' ;
     *
     * In this method we build a crooked tree, which in a later phase needs to be balanced
     * according to the priorities of the operators.
     * @param branch
     * @private
     */
    public transform__fre_binary_ScheduleExpression(
        nodeInfo: SpptDataNodeInfo,
        children: KtList<any>,
        sentence: Sentence,
    ): ScheduleExpression {
        // console.log('transform__fre_binary_ScheduleExpression called: ' + children.toString());
        let index = 0;
        let list = children.asJsReadonlyArrayView();
        let first = list[index++];
        while (index < list.length) {
            let operator = list[index++];
            let second = list[index++];
            let combined: ScheduleExpression | null = null;
            switch (operator) {
                case "*": {
                    combined = MultiplyExpression.create({
                        left: first,
                        right: second,
                        parseLocation: this.mainAnalyser.location(sentence, nodeInfo.node),
                    });
                    break;
                }
                case "+": {
                    combined = PlusExpression.create({
                        left: first,
                        right: second,
                        parseLocation: this.mainAnalyser.location(sentence, nodeInfo.node),
                    });
                    break;
                }
                case "-": {
                    combined = MinusExpression.create({
                        left: first,
                        right: second,
                        parseLocation: this.mainAnalyser.location(sentence, nodeInfo.node),
                    });
                    break;
                }
                case "/": {
                    combined = DivideExpression.create({
                        left: first,
                        right: second,
                        parseLocation: this.mainAnalyser.location(sentence, nodeInfo.node),
                    });
                    break;
                }
                case "and": {
                    combined = AndExpression.create({
                        left: first,
                        right: second,
                        parseLocation: this.mainAnalyser.location(sentence, nodeInfo.node),
                    });
                    break;
                }
                case "or": {
                    combined = OrExpression.create({
                        left: first,
                        right: second,
                        parseLocation: this.mainAnalyser.location(sentence, nodeInfo.node),
                    });
                    break;
                }
                case "<": {
                    combined = LessThenExpression.create({
                        left: first,
                        right: second,
                        parseLocation: this.mainAnalyser.location(sentence, nodeInfo.node),
                    });
                    break;
                }
                case ">": {
                    combined = GreaterThenExpression.create({
                        left: first,
                        right: second,
                        parseLocation: this.mainAnalyser.location(sentence, nodeInfo.node),
                    });
                    break;
                }
                case "==": {
                    combined = EqualsExpression.create({
                        left: first,
                        right: second,
                        parseLocation: this.mainAnalyser.location(sentence, nodeInfo.node),
                    });
                    break;
                }
                default: {
                    combined = null;
                }
            }
            first = combined;
        }
        return first;
    }

    /**
     * Method to transform branches that match the following rule:
     * TimeUnit = '\`hours\`'
     *	| '\`days\`'
     *	| '\`weeks\`'
     *	| '\`months\`' ;
     * @param nodeInfo
     * @param children
     * @param sentence
     */
    public transformTimeUnit(
        nodeInfo: SpptDataNodeInfo,
        children: KtList<any>,
        sentence: Sentence,
    ): FreNodeReference<TimeUnit> | undefined {
        // console.log('5 transformTimeUnit called: ' + children.toString());
        let result: FreNodeReference<TimeUnit> | undefined;
        const child: string = children.asJsReadonlyArrayView()[0];
        // todo make sure we remove only the outer quotes
        const name: string = child.replace(/`/g, "");
        switch (name) {
            case "hours": {
                result = FreNodeReference.create<TimeUnit>(TimeUnit.hours, "TimeUnit");
                break;
            }
            case "days": {
                result = FreNodeReference.create<TimeUnit>(TimeUnit.days, "TimeUnit");
                break;
            }
            case "weeks": {
                result = FreNodeReference.create<TimeUnit>(TimeUnit.weeks, "TimeUnit");
                break;
            }
            case "months": {
                result = FreNodeReference.create<TimeUnit>(TimeUnit.months, "TimeUnit");
                break;
            }
            default:
                result = undefined;
        }
        if (result !== undefined) {
            result.parseLocation = this.mainAnalyser.location(sentence, nodeInfo.node);
        }
        return result;
    }

